<script setup lang="ts">
definePageMeta({layout:'consumer'})
const {profiles,profileId,request,requireSession,loadProfiles,selectProfile,signOut}=useConsumer()
const name=ref(''),renaming=ref(''),renameValue=ref(''),displayName=ref(''),email=ref(''),productEmails=ref(false),links=ref<{id:string;shareUrl:string;expiresAt:string|null;isActive:boolean;createdAt:string}[]>([])
const expiry=ref(7),account=ref<Record<string,unknown>>({}),error=ref(''),message=ref(''),busy=ref(false),loading=ref(true),shareUrl=ref('')
useHead({title:'You | Doclyzer'})
async function load(){loading.value=true;error.value='';try{await loadProfiles();const [a,p]=await Promise.all([request<Record<string,unknown>>('/account/profile'),request<{productEmails:boolean}>('/account/communication-preferences')]);account.value=a;displayName.value=String(a.displayName??'');email.value=String(a.email??'');productEmails.value=p.productEmails;await loadLinks()}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
async function loadLinks(){const id=profileId.value;links.value=[];shareUrl.value='';const rows=id?await request<typeof links.value>(`/sharing/links?profileId=${encodeURIComponent(id)}`):[];if(id===profileId.value)links.value=rows}
onMounted(async()=>{if(await requireSession())await load()});watch(profileId,()=>{if(!loading.value)void loadLinks()})
async function act(task:()=>Promise<unknown>,success:string){busy.value=true;error.value='';message.value='';try{await task();message.value=success}catch(cause){error.value=(cause as Error).message}finally{busy.value=false}}
async function addProfile(){if(!name.value.trim())return;await act(async()=>{const p=await request<{id:string}>('/profiles',{method:'POST',body:{name:name.value.trim()}});name.value='';await loadProfiles();await selectProfile(p.id)},'Profile added.')}
async function renameProfile(id:string){if(!renameValue.value.trim())return;await act(async()=>{await request(`/profiles/${id}`,{method:'PATCH',body:{name:renameValue.value.trim()}});renaming.value='';await loadProfiles()},'Profile updated.')}
async function removeProfile(id:string){if(!confirm('Delete this profile? Its associated reports may also be removed.'))return;await act(async()=>{await request(`/profiles/${id}`,{method:'DELETE'});await loadProfiles()},'Profile deleted.')}
async function saveAccount(){await act(async()=>{await request('/account/profile',{method:'PATCH',body:{displayName:displayName.value}});await request('/account/communication-preferences',{method:'PUT',body:{productEmails:productEmails.value}})},'Settings saved.')}
async function createLink(){await act(async()=>{const link=await request<{shareUrl:string}>('/sharing/links',{method:'POST',body:{profileId:profileId.value,expiresAt:new Date(Date.now()+expiry.value*86400000).toISOString()}});shareUrl.value=link.shareUrl;await loadLinks();shareUrl.value=link.shareUrl},'Share link created.')}
async function revoke(id:string){if(!confirm('Revoke this link? Anyone using it will lose access.'))return;await act(async()=>{await request(`/sharing/links/${id}`,{method:'DELETE'});await loadLinks()},'Link revoked.')}
async function copy(url:string){await navigator.clipboard.writeText(url);message.value='Link copied.'}
</script>
<template><div><header class="page-heading"><div><p class="eyebrow">Account and family</p><h1>You</h1><p class="muted">Manage who your reports belong to and who can see them.</p></div></header><p v-if="loading" role="status">Loading settings…</p><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="message" role="status" class="alert success">{{ message }}</p><template v-if="!loading"><section class="card"><h2>Profiles</h2><div v-for="p in profiles" :key="p.id" class="row profile"><span><strong>{{ p.name }}</strong> <span v-if="p.id===profileId">· Viewing now</span></span><div class="actions"><button v-if="p.id!==profileId" class="secondary" @click="act(()=>selectProfile(p.id),'Profile switched.')">Switch</button><button class="secondary" @click="renaming=p.id;renameValue=p.name">Rename</button><button class="text-button" :disabled="busy" @click="removeProfile(p.id)">Delete</button></div><form v-if="renaming===p.id" class="row" @submit.prevent="renameProfile(p.id)"><label class="field">Profile name<input v-model="renameValue" maxlength="100" required /></label><button :disabled="busy">Save name</button><button type="button" class="secondary" @click="renaming=''">Cancel</button></form></div><form class="row" @submit.prevent="addProfile"><label class="field">Add a family profile<input v-model="name" maxlength="100" placeholder="Name" required /></label><button :disabled="busy">Add profile</button></form></section><section class="card"><h2>Sharing</h2><p>New links show all reports and results for <strong>{{ profiles.find(p=>p.id===profileId)?.name }}</strong>. Anyone with the link can view them until expiry or revocation.</p><div v-if="profileId" class="row"><label class="field">Link expires after<select v-model.number="expiry"><option :value="1">1 day</option><option :value="7">7 days</option><option :value="30">30 days</option></select></label><button :disabled="busy" @click="createLink">Create share link</button></div><div v-if="shareUrl" class="alert success"><p>Share this link with the intended recipient:</p><input :value="shareUrl" readonly aria-label="New share link" /><button class="secondary" @click="copy(shareUrl)">Copy</button></div><div v-for="link in links" :key="link.id" class="row share"><div><strong>{{ link.isActive ? 'Active link' : 'Revoked link' }}</strong><p>Expires {{ link.expiresAt ? new Date(link.expiresAt).toLocaleString() : 'never' }}</p></div><div class="actions"><button v-if="link.isActive" class="secondary" @click="copy(link.shareUrl)">Copy</button><button v-if="link.isActive" class="secondary" :disabled="busy" @click="revoke(link.id)">Revoke</button></div></div><p v-if="!links.length">No share links for this profile.</p></section><section class="card"><h2>Account</h2><p v-if="email">{{ email }}</p><form class="stack" @submit.prevent="saveAccount"><label class="field">Display name<input v-model="displayName" maxlength="100" /></label><label><input v-model="productEmails" type="checkbox" /> Receive product emails</label><div><button :disabled="busy">Save settings</button></div></form></section><section class="card"><h2>Privacy and access</h2><div class="actions"><button class="secondary" :disabled="busy" @click="act(()=>request('/account/data-export-requests',{method:'POST',body:{}}),'Data export requested. Check your email for updates.')">Request a data export</button><NuxtLink class="button secondary" to="/you/sessions">Manage sessions</NuxtLink><NuxtLink class="button secondary" to="/you/close-account">Close account</NuxtLink></div></section><button class="secondary" @click="signOut">Sign out</button></template></div></template>
<style scoped>.share,.profile{border-top:1px solid #dce6dc;padding:12px 0}.profile form{width:100%}.share p{margin:4px 0}.alert input{width:min(100%,500px);padding:9px;margin-right:8px}</style>
